WITH base AS (SELECT *, UPPER(device) AS device_upper, HOUR(started_at) AS started_at_hour, COALESCE(country, 'N/A') AS resolved_country FROM sessions WHERE country = 'SG'), gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) > INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM base), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT browser, device, COUNT(*) AS num_rows, MAX(session_no) FILTER (WHERE country = 'TH') AS th_max_session_no, ROUND(SUM(new_group_flag) / NULLIF(COUNT(CASE WHEN country = 'JP' THEN 1 END), 0), 2) AS new_group_flag_per_jp FROM sessionized GROUP BY GROUPING SETS ((browser, device), (browser))
